61	     *  applies from the beginning of time. */
62	    @Transactional
63	    public Person add(String sheetId, String user, String name, String grade, Integer terms) {
64	        return add(sheetId, user, name, grade, terms, null);
65	    }
66	
67	    /** Add a person to the sheet with their own terms (null for none) and a contact (blank for none);
68	     *  the grade they are given applies from the beginning of time. */
69	    @Transactional
70	    public Person add(String sheetId, String user, String name, String grade, Integer terms, String contact) {
71	        LocalDate today = sheets.today(sheetId);
72	        String trimmed = name.trim();
73	        requireFreeName(sheetId, trimmed, null);
74	        String key = contactKey(contact);
75	        requireFreeContact(sheetId, key, null);
76	        Person person = new Person(sheetId, trimmed, today);
77	        person.setTerms(terms);
78	        person.setContact(key);
79	        Person added = people.saveAndFlush(person);
80	        grades.give(added, grade, null);
81	        record("PERSON_ADDED", sheetId, user, added, grade, (terms != null ? " terms=" + terms : "")
82	                + (key != null ? " contact=" + key : ""));
83	        return added;
84	    }
85	
86	    /** Change a person's name, and give them the grade from a date (blank takes the sheet's today),
87	     *  keeping the grades already given, and set their own terms (null for none) and contact (blank for none), from an editor that loaded the given version of them. A
88	     *  blank from-date with the grade in force on the sheet's today gives no grade. */
89	    @Transactional
90	    public Person update(String sheetId, String user, Long id, long version, String name, String grade,
91	            LocalDate gradeFrom, Integer terms, String contact) {
92	        Person person = people.findByIdAndSheetId(id, sheetId)
93	                .orElseThrow(() -> new NoSuchElementException("No person " + id + " on sheet " + sheetId));
94	        if (person.getVersion() != version) {
95	            throw new StalePersonException(person);
96	        }
97	        String trimmed = name.trim();
98	        requireFreeName(sheetId, trimmed, id);
99	        List<String> tree = sheets.tree(sheetId);
100	        if (!tree.isEmpty()) {
101	            for (PersonAlias alias : aliases.findByPersonIdOrderByIdAsc(id)) {
102	                if (inUseOnTree(tree, alias.getAlias())) {
103	                    throw new NameInUseException(alias.getAlias());
104	                }
105	            }
106	        }
107	        String key = contactKey(contact);
108	        requireFreeContact(sheetId, key, id);
109	        person.setName(trimmed);
110	        Integer before = person.getTerms();
111	        person.setTerms(terms);
112	        String contactBefore = person.getContact();
113	        person.setContact(key);
114	        LocalDate today = sheets.today(sheetId);
115	        if (gradeFrom != null || !grade.equals(grades.gradeOn(id, today))) {
116	            grades.give(person, grade, gradeFrom != null ? gradeFrom : today);
117	            // A grade given changes the person, so an editor that loaded them before is stale.
118	            entityManager.lock(person, LockModeType.PESSIMISTIC_FORCE_INCREMENT);
119	        }
120	        Person saved = people.saveAndFlush(person);
121	        record("PERSON_EDITED", sheetId, user, saved, grades.gradeOn(id, today),
122	                (Objects.equals(before, terms) ? "" : " terms=" + (terms != null ? terms : ""))
123	                + (Objects.equals(contactBefore, key) ? "" : " contact=" + (key != null ? key : "")));
124	        return saved;
125	    }
126	
127	    /** Retire a person from a date; a missing date takes the sheet's today. */
128	    @Transactional
129	    public Person retire(String sheetId, String user, Long id, LocalDate from) {
130	        Person person = people.findByIdAndSheetId(id, sheetId)
131	                .orElseThrow(() -> new NoSuchElementException("No person " + id + " on sheet " + sheetId));
132	        LocalDate on = from != null ? from : sheets.today(sheetId);
133	        person.setRetiredFrom(on);
134	        Person saved = people.saveAndFlush(person);
135	        audit.recordOnCommit("PERSON_RETIRED sheet=" + sheetId + " by=" + user + " name=" + saved.getName()
136	                + " from=" + on);
137	        return saved;
138	    }
139	
140	    /** Put a hold on a person from a date (a missing date takes the sheet's today) to an optional
141	     *  to-date, keeping the holds they have; refused when the to-date is before the from-date. */
142	    @Transactional
143	    public Person hold(String sheetId, String user, Long id, LocalDate from, LocalDate to) {
144	        Person person = people.findByIdAndSheetId(id, sheetId)
145	                .orElseThrow(() -> new NoSuchElementException("No person " + id + " on sheet " + sheetId));
146	        LocalDate on = from != null ? from : sheets.today(sheetId);
147	        if (to != null && to.isBefore(on)) {
148	            throw new HoldRefusedException("The hold's to-date " + to + " is before its from-date " + on);
149	        }
150	        holds.saveAndFlush(new PersonHold(sheetId, id, on, to, sheets.today(sheetId)));
151	        audit.recordOnCommit("PERSON_HELD sheet=" + sheetId + " by=" + user + " name=" + person.getName()
152	                + " from=" + on);
153	        return person;
154	    }
155	
156	    /** Each person's holds on the sheet, in the order they were put on, by person id; a person with
157	     *  none is absent. */
158	    public Map<Long, List<PersonHold>> holds(String sheetId) {
159	        return holds.findBySheetIdOrderByIdAsc(sheetId).stream()
160	                .collect(Collectors.groupingBy(PersonHold::getPersonId));
161	    }
162	
163	    /** A person's holds, in the order they were put on. */
164	    public List<PersonHold> holds(Long personId) {
165	        return holds.findByPersonIdOrderByIdAsc(personId);
166	    }
167	
168	    /** A person's holds as they stood at the end of a day: those put on while the sheet's today was
169	     *  on or before it, in the order they were put on. */
170	    public List<PersonHold> holdsAsOf(Long personId, LocalDate day) {
171	        return holds(personId).stream().filter(hold -> hold.madeAsOf(day)).toList();
172	    }
173	
174	    /** Each person's patron ids on the sheet, in the order they were named, by person id; a person
175	     *  with none is absent. */
176	    public Map<Long, List<Long>> patronIds(String sheetId) {
177	        return patrons.findBySheetIdOrderByIdAsc(sheetId).stream()
178	                .collect(Collectors.groupingBy(PersonPatron::getPersonId,
179	                        Collectors.mapping(PersonPatron::getPatronId, Collectors.toList())));
180	    }
181	
182	    /** Each person's patron ids on the sheet as they stood at the end of a day, in the order they were
183	     *  named, by person id (null: as they stand now); a person with none is absent. */
184	    public Map<Long, List<Long>> patronIds(String sheetId, LocalDate asOf) {
185	        return patrons.findBySheetIdOrderByIdAsc(sheetId).stream()
186	                .filter(patron -> asOf == null || patron.madeAsOf(asOf))
187	                .collect(Collectors.groupingBy(PersonPatron::getPersonId,
188	                        Collectors.mapping(PersonPatron::getPatronId, Collectors.toList())));
189	    }
190	
191	    /** Each person's holds on the sheet as they stood at the end of a day, in the order they were put
192	     *  on, by person id (null: as they stand now); a person with none is absent. */
193	    public Map<Long, List<PersonHold>> holds(String sheetId, LocalDate asOf) {
194	        return holds.findBySheetIdOrderByIdAsc(sheetId).stream()
195	                .filter(hold -> asOf == null || hold.madeAsOf(asOf))
196	                .collect(Collectors.groupingBy(PersonHold::getPersonId));
197	    }
198	
199	    /** The ids of the people a user watched on the sheet at the end of a day (null: now). */
200	    public Set<Long> watchedIds(String sheetId, String user, LocalDate asOf) {
201	        Set<Long> now = watchedIds(sheetId, user);
202	        return asOf == null ? now : history.watched(sheetId, user, now, asOf);
203	    }
204	
205	    /** The sheet's people as they stood at the end of a day, in the order they were added: those added
206	     *  by then (those since merged into another included), each with the name, own terms, retirement and
207	     *  contact they had then (null: as they stand now). */
208	    public List<Person> list(String sheetId, LocalDate asOf) {
209	        if (asOf == null) {
210	            return list(sheetId);
211	        }
212	        Map<Long, History.PersonThen> then = history.people(sheetId, asOf);
213	        return people.findEverBySheetId(sheetId).stream().filter(person -> person.onSheetAsOf(asOf)).map(person -> {
214	            History.PersonThen was = then.get(person.getId());
215	            return was == null ? person : person.asItWas(was.name(), was.terms(), was.retiredFrom(), was.contact());
216	        }).toList();
217	    }
218	
219	    /** A person's patron ids, in the order they were named. */
220	    public List<Long> patronIds(Long personId) {
221	        return patrons.findByPersonIdOrderByIdAsc(personId).stream().map(PersonPatron::getPatronId).toList();
222	    }
223	
224	    /** Name another person on the sheet as a person's patron; refused for the person themselves and
225	     *  for someone already their patron. */
226	    @Transactional
227	    public Person addPatron(String sheetId, String user, Long id, Long patronId) {
228	        Person person = people.findByIdAndSheetId(id, sheetId)
229	                .orElseThrow(() -> new NoSuchElementException("No person " + id + " on sheet " + sheetId));
230	        Person patron = people.findByIdAndSheetId(patronId, sheetId)
231	                .orElseThrow(() -> new NoSuchElementException("No person " + patronId + " on sheet " + sheetId));
232	        if (person.getId().equals(patron.getId())) {
233	            throw new PatronRefusedException(person.getName() + " cannot be their own patron");
234	        }
235	        if (patrons.existsByPersonIdAndPatronId(person.getId(), patron.getId())) {
236	            throw new PatronRefusedException(patron.getName() + " is already a patron of " + person.getName());
237	        }
238	        patrons.saveAndFlush(new PersonPatron(sheetId, person.getId(), patron.getId(), sheets.today(sheetId)));
239	        audit.recordOnCommit("PATRON_ADDED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
240	                + " patron=" + patron.getName());
241	        return person;
242	    }
243	
244	    /** Give a person an alias, trimmed; refused when blank, or when it equals, as names are compared,
245	     *  any name or alias on the sheet or on any other sheet of its tree. */
246	    @Transactional
247	    public Person addAlias(String sheetId, String user, Long id, String alias) {
248	        Person person = people.findByIdAndSheetId(id, sheetId)
249	                .orElseThrow(() -> new NoSuchElementException("No person " + id + " on sheet " + sheetId));
250	        String trimmed = alias == null ? "" : alias.trim();
251	        if (trimmed.isEmpty()) {
252	            throw new AliasRefusedException("An alias may not be blank");
253	        }
254	        if (people.nameInUse(sheetId, trimmed, null) || aliases.aliasInUse(sheetId, trimmed)
255	                || inUseOnTree(sheets.tree(sheetId), trimmed)) {
256	            throw new NameInUseException(trimmed);
257	        }
258	        aliases.saveAndFlush(new PersonAlias(sheetId, id, trimmed, sheets.today(sheetId)));
259	        audit.recordOnCommit("PERSON_ALIAS_ADDED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
260	                + " alias=" + trimmed);
261	        return person;
262	    }
263	
264	    /** A person's aliases, sorted as names are compared. */
265	    public List<String> aliases(Long personId) {
266	        return sorted(aliases.findByPersonIdOrderByIdAsc(personId).stream());
267	    }
268	
269	    /** Each person's aliases on the sheet as they stood at the end of a day, sorted as names are
270	     *  compared, by person id (null: as they stand now); a person with none is absent. */
271	    public Map<Long, List<String>> aliases(String sheetId, LocalDate asOf) {
272	        return aliases.findBySheetIdOrderByIdAsc(sheetId).stream()
273	                .filter(alias -> asOf == null || alias.madeAsOf(asOf))
274	                .collect(Collectors.groupingBy(PersonAlias::getPersonId,
275	                        Collectors.collectingAndThen(Collectors.toList(), list -> sorted(list.stream()))));
276	    }
277	
278	    private static List<String> sorted(java.util.stream.Stream<PersonAlias> stream) {
279	        return stream.map(PersonAlias::getAlias)
280	                .sorted(java.util.Comparator.comparing((String a) -> a.toLowerCase(Locale.ROOT))
281	                        .thenComparing(java.util.Comparator.naturalOrder()))
282	                .toList();
283	    }
284	
285	    /** Start or stop a user watching a person; a person already in that state is left as they are,
286	     *  writing nothing. */
287	    @Transactional
288	    public Person watch(String sheetId, String user, Long id, boolean on) {
289	        Person person = people.findByIdAndSheetId(id, sheetId)
290	                .orElseThrow(() -> new NoSuchElementException("No person " + id + " on sheet " + sheetId));
291	        var existing = watches.findByPersonIdAndUser(id, user);
292	        if (on && existing.isEmpty()) {
293	            watches.saveAndFlush(new PersonWatch(sheetId, id, user));
294	            history.watchSet(sheetId, id, user, true);
295	            audit.recordOnCommit("PERSON_WATCHED sheet=" + sheetId + " by=" + user + " name=" + person.getName());
296	        } else if (!on && existing.isPresent()) {
297	            watches.delete(existing.get());
298	            watches.flush();
299	            history.watchSet(sheetId, id, user, false);
300	            audit.recordOnCommit("PERSON_UNWATCHED sheet=" + sheetId + " by=" + user + " name=" + person.getName());
301	        }
302	        return person;
303	    }
304	
305	    /** The ids of the people a user watches on the sheet. */
306	    public Set<Long> watchedIds(String sheetId, String user) {
307	        return watches.findBySheetIdAndUser(sheetId, user).stream().map(PersonWatch::getPersonId)
308	                .collect(Collectors.toSet());
309	    }
310	
311	    /** Whether a user watches a person. */
312	    public boolean watches(Long personId, String user) {
313	        return watches.findByPersonIdAndUser(personId, user).isPresent();
314	    }
315	
316	    /** A person's watchers, in the order they started watching. */
317	    public List<String> watchers(Long personId) {
318	        return watches.findByPersonIdOrderByIdAsc(personId).stream().map(PersonWatch::getUser).toList();
319	    }
320	
321	    private void record(String event, String sheetId, String user, Person person, String grade, String terms) {
322	        audit.recordOnCommit(event + " sheet=" + sheetId + " by=" + user
323	                + " name=" + person.getName() + " grade=" + grade + terms);
324	    }
325	
326	    /** A contact as kept: trimmed and lower-cased; null for a blank one. */
327	    private static String contactKey(String contact) {
328	        if (contact == null || contact.isBlank()) {
329	            return null;
330	        }
331	        return contact.trim().toLowerCase(Locale.ROOT);
332	    }
333	
334	    private void requireFreeContact(String sheetId, String contact, Long exceptId) {
335	        if (contact != null && people.contactInUse(sheetId, contact, exceptId)) {
336	            throw new ContactInUseException(contact);
337	        }
338	    }
339	
340	    /** Refuse a name used, as names are compared, by another person on the sheet (not {@code exceptId}),
341	     *  by an alias on the sheet, or as a name or alias on any other sheet of its tree. */
342	    private void requireFreeName(String sheetId, String name, Long exceptId) {
343	        if (people.nameInUse(sheetId, name, exceptId) || aliases.aliasInUse(sheetId, name)
344	                || inUseOnTree(sheets.tree(sheetId), name)) {
345	            throw new NameInUseException(name);
346	        }
347	    }
348	
349	    /** Whether a name or alias on any of the tree's sheets is this name, as names are compared. */
350	    private boolean inUseOnTree(List<String> tree, String name) {
351	        return !tree.isEmpty() && (people.nameInUseOn(tree, name) || aliases.aliasInUseOn(tree, name));
352	    }
353	
354	    /** The names and aliases on the other sheets of the sheet's tree, lower-cased. */
355	    private Set<String> treeKeys(String sheetId) {
356	        List<String> tree = sheets.tree(sheetId);
357	        if (tree.isEmpty()) {
358	            return Set.of();
359	        }
360	        Set<String> keys = new java.util.HashSet<>(people.nameKeysOn(tree));
361	        keys.addAll(aliases.aliasKeysOn(tree));
362	        return keys;
363	    }
364	
365	    private static boolean clashes(Set<String> treeKeys, String name, List<String> theirAliases) {
366	        return treeKeys.contains(name.toLowerCase(Locale.ROOT))
367	                || theirAliases.stream().anyMatch(alias -> treeKeys.contains(alias.toLowerCase(Locale.ROOT)));
368	    }
369	
370	    /** Whether the person clashes: their name or an alias of theirs is used as a name or alias on
371	     *  another sheet of their sheet's tree. */
372	    public boolean clashing(Person person) {
373	        return clashes(treeKeys(person.getSheetId()), person.getName(), aliases(person.getId()));
374	    }
375	
376	    /** The ids of the people on the sheet who clash, as {@link #clashing(Person)} judges, with the
377	     *  names and aliases given them. */
378	    public Set<Long> clashingIds(String sheetId, List<Person> them, Map<Long, List<String>> theirAliases) {
379	        Set<String> keys = treeKeys(sheetId);
380	        if (keys.isEmpty()) {
381	            return Set.of();
382	        }
383	        return them.stream().filter(p -> clashes(keys, p.getName(), theirAliases.getOrDefault(p.getId(), List.of())))
384	                .map(Person::getId).collect(Collectors.toSet());
385	    }
386	}
